    },
    'brush-2048-diagonal': brush,
    'tiled-sparse-32768-patch': { ...tiled, allocatedBytes: sparseAllocatedBytes },
    'coverage-sparse-32768-patch': {
      ...tiledCoverage,
      allocatedBytes: sparseCoverageAllocatedBytes,
    },
    'document-1024-8-memory': {
      logicalPayloadBytes,
      arrayBufferDeltaBytes,
      arrayBufferAmplification,
      heapDeltaBytes: memoryAfter.heapUsed - memoryBefore.heapUsed,
    },
    'dense-4096-x20-progressive': {
      medianMs: denseProgressiveViewport.medianMs,
      p95Ms: denseProgressiveViewport.p95Ms,
      samplesMs: denseProgressiveViewport.samplesMs,
      allocatedBytes: denseProgressiveCache.allocatedByteLength,
      cacheStats: {
        hits: denseStats.hits,
        misses: denseStats.misses,
        lastComposeFullyWarm: denseStats.lastComposeFullyWarm,
        uniqueSpatialTileCount: denseStats.uniqueSpatialTileCount,
      },
    },
    'sparse-8192-progressive': {
      medianMs: sparseProgressiveViewport.medianMs,
      p95Ms: sparseProgressiveViewport.p95Ms,
      samplesMs: sparseProgressiveViewport.samplesMs,
      allocatedBytes: sparseProgressiveCache.allocatedByteLength,
      cacheStats: {
        hits: sparseStats.hits,
        misses: sparseStats.misses,
        lastComposeFullyWarm: sparseStats.lastComposeFullyWarm,
        uniqueSpatialTileCount: sparseStats.uniqueSpatialTileCount,
      },
    },
    'sustained-pan-memory': {
      peakAllocatedBytes,
      finalAllocatedBytes: memoryTestCache.allocatedByteLength,
      totalEvictions,
      uniqueSpatialTileCount: finalMemoryStats.uniqueSpatialTileCount,
      growthFactor,
      firstHalfAvgAllocatedBytes: firstHalfAvg,
      secondHalfAvgAllocatedBytes: secondHalfAvg,
      iterationCount,
      viewportSize: viewportBudget,
    },
  },
};

process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);

