// ============================================================================
// INCOMPLETE MILESTONE 4: Sustained Progressive Pan Memory (Node)
// ============================================================================

// Node benchmark that validates sustained memory behavior under progressive pan
// operations with LRU eviction tracking.
// Based on browser evidence: peak 2.5 MiB, 1024 evictions, stayed within budget.

const memoryTestDocument = layeredDocument(1024, 1024, 6);

// Use a tight cache budget to force eviction behavior
const memoryTestCache = new CompositeTileCache({
  tileSize: 64,
  maxBytes: 2.5 * 1024 * 1024, // 2.5 MiB budget matching browser evidence
});

const memoryTestReference = (doc: ImageDocument) => compositeDocumentPixels(doc);
memoryTestCache.composite(memoryTestDocument, { referenceComposite: memoryTestReference });

// Simulate progressive panning: multiple viewport positions
const panPositions = [
  { x: 0, y: 0 },
  { x: 256, y: 0 },
  { x: 512, y: 0 },
  { x: 768, y: 0 },
  { x: 0, y: 256 },
  { x: 256, y: 256 },
  { x: 512, y: 256 },
  { x: 768, y: 256 },
  { x: 0, y: 512 },
  { x: 256, y: 512 },
  { x: 512, y: 512 },
  { x: 768, y: 512 },
  { x: 0, y: 768 },
  { x: 256, y: 768 },
  { x: 512, y: 768 },
  { x: 768, y: 768 },
];

const viewportBudget = 384;
const iterationCount = 48; // Match browser's 48 pan+edit iterations

let peakAllocatedBytes = 0;
const allocationHistory: number[] = [];

// Run sustained pan test
for (let iteration = 0; iteration < iterationCount; iteration++) {
  // Cycle through pan positions
  const position = panPositions[iteration % panPositions.length];

  // Render viewport at this position
  const output = memoryTestCache.composite(memoryTestDocument, {
    referenceComposite: memoryTestReference,
    progressiveViewportOnly: true,
    viewportRegion: {
      x: position.x,
      y: position.y,
      width: viewportBudget,
      height: viewportBudget,
    },
  });

  if (output.length !== viewportBudget * viewportBudget * 4) {
    throw new Error('Sustained pan viewport output size changed');
  }

  // Track allocation metrics
  const currentAllocated = memoryTestCache.stats.allocatedBytes;
  peakAllocatedBytes = Math.max(peakAllocatedBytes, currentAllocated);
  allocationHistory.push(currentAllocated);

  if (iteration % 10 === 0) {
    console.log(`Sustained pan iteration ${iteration}: allocated=${currentAllocated}, peak=${peakAllocatedBytes}, evictions=${memoryTestCache.stats.evictions}`);
  }
}

const finalMemoryStats = memoryTestCache.stats;

console.log('Sustained pan memory test results:', {
  peakAllocatedBytes,
  finalAllocatedBytes: memoryTestCache.stats.allocatedBytes,
  totalEvictions: finalMemoryStats.evictions,
  uniqueSpatialTileCount: finalMemoryStats.uniqueSpatialTileCount,
  tileCount: finalMemoryStats.tileCount,
});

// Validate budget constraints
const memoryBudget = baselines.scenarios['sustained-pan-memory'];

if (peakAllocatedBytes > memoryBudget.maxCacheBytes) {
  throw new Error(
    `sustained-pan-memory exceeded cache budget: peak ${peakAllocatedBytes} bytes (budget: ${memoryBudget.maxCacheBytes})`,
  );
}

// Check bounded growth: second half should not exceed first half by more than factor
const halfPoint = Math.floor(allocationHistory.length / 2);
const firstHalfAvg = allocationHistory.slice(0, halfPoint).reduce((a, b) => a + b, 0) / halfPoint;
const secondHalfAvg = allocationHistory.slice(halfPoint).reduce((a, b) => a + b, 0) / (allocationHistory.length - halfPoint);

const growthFactor = secondHalfAvg / firstHalfAvg;
console.log('Sustained pan growth analysis:', {
  firstHalfAvg,
  secondHalfAvg,
  growthFactor,
});

if (growthFactor > memoryBudget.maxBoundedGrowthFactor) {
  throw new Error(
    `sustained-pan-memory unbounded growth: factor ${growthFactor.toFixed(2)} (budget: ${memoryBudget.maxBoundedGrowthFactor})`,
  );
}

