import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import {
  createDocument,
  createPixelLayer,
  type ImageDocument,
  type PixelLayer,
} from '@freetoshop/core-document';
import { paintStroke } from '@freetoshop/raster-engine';
import {
  CompositeTileCache,
  compositeDocumentPixels,
  compositeDocumentRegion,
} from '@freetoshop/renderer';
import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

interface TimingBudget {
  readonly maxMedianMs: number;
  readonly maxP95Ms: number;
}

interface Baselines {
  readonly schemaVersion: 1;
  readonly profile: string;
  readonly scenarios: {
    readonly 'composite-512-12': TimingBudget;
    readonly 'brush-2048-diagonal': TimingBudget;
    readonly 'tiled-sparse-32768-patch': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'coverage-sparse-32768-patch': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'document-1024-8-memory': { readonly maxArrayBufferAmplification: number };
    readonly 'composite-tile-cache-warm-128-4'?: TimingBudget;
    readonly 'composite-tile-cache-warm-512-8'?: TimingBudget;
    readonly 'dense-4096-x20-progressive': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'sparse-8192-progressive': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'sustained-pan-memory': { readonly maxCacheBytes: number; readonly maxBoundedGrowthFactor: number };
  };
}

interface TimingResult {
  readonly medianMs: number;
  readonly p95Ms: number;
  readonly samplesMs: readonly number[];
}

const baselinePath = fileURLToPath(new URL('../baselines.json', import.meta.url));
const baselines = JSON.parse(await readFile(baselinePath, 'utf8')) as Baselines;

function solidLayer(id: string, width: number, height: number, seed: number): PixelLayer {
  const pixels = new Uint8ClampedArray(width * height * 4);
  for (let offset = 0; offset < pixels.length; offset += 4) {
    pixels[offset] = (seed * 37 + offset / 4) % 256;
    pixels[offset + 1] = (seed * 71 + offset / 16) % 256;
    pixels[offset + 2] = (seed * 113 + offset / 64) % 256;
    pixels[offset + 3] = 224;
  }
  return createPixelLayer({
    id,
    name: id,
    width,
    height,
    pixels,
    opacity: 0.8,
    blendMode: seed % 3 === 0 ? 'multiply' : seed % 3 === 1 ? 'screen' : 'normal',
  });
}

function layeredDocument(width: number, height: number, layerCount: number): ImageDocument {
  return createDocument({
    id: `benchmark-${String(width)}-${String(layerCount)}`,
    name: 'Benchmark document',
    width,
    height,
    layers: Array.from({ length: layerCount }, (_, index) =>
      solidLayer(`layer-${String(index)}`, width, height, index + 1),
    ),
  });
}

function percentile(sorted: readonly number[], fraction: number): number {
  const index = Math.min(sorted.length - 1, Math.ceil(sorted.length * fraction) - 1);
  return sorted[index] ?? 0;
}

function benchmark(operation: () => void, warmups = 1, samples = 5): TimingResult {
  for (let index = 0; index < warmups; index += 1) operation();
  const durations: number[] = [];
  for (let index = 0; index < samples; index += 1) {
    const started = performance.now();
    operation();
    durations.push(performance.now() - started);
  }
  durations.sort((left, right) => left - right);
  return {
    medianMs: percentile(durations, 0.5),
    p95Ms: percentile(durations, 0.95),
    samplesMs: durations,
  };
}

function assertTiming(name: string, result: TimingResult, budget: TimingBudget): void {
  if (result.medianMs > budget.maxMedianMs || result.p95Ms > budget.maxP95Ms) {
    throw new Error(
      `${name} exceeded its baseline: median ${result.medianMs.toFixed(1)} ms, p95 ${result.p95Ms.toFixed(1)} ms`,
    );
  }
}

function getAllocatedBytes(cache: CompositeTileCache): number {
  return cache.stats.allocatedBytes;
}

function getTotalEvictions(cache: CompositeTileCache): number {
  return cache.stats.evictions;
}

async function settleMemoryAccounting(): Promise<void> {
  globalThis.gc?.();
  await new Promise<void>((resolve) => setImmediate(resolve));
  globalThis.gc?.();
  await new Promise<void>((resolve) => setImmediate(resolve));
  globalThis.gc?.();
}

// ============================================================================
// INCOMPLETE MILESTONE 2: Dense 4096×4096 × 20 Layers Progressive Composite
// ============================================================================

// Node benchmark for the largest dense fixture: 4096² × 20 layer progressive composite.
// Based on browser evidence: cold ~232ms, warm ~45ms.
// Uses compositeDocumentRegion for true viewport-only rendering (returns only viewport pixels)

const denseProgressiveDocument = layeredDocument(4096, 4096, 20);

// Cache for warm re-composites
const denseProgressiveCache = new CompositeTileCache({
  tileSize: 256,
  maxBytes: 256 * 1024 * 1024, // 256 MiB budget for this large fixture
});

// First warm-up: populate the cache with full composite
denseProgressiveCache.composite(denseProgressiveDocument, {
  referenceComposite: compositeDocumentPixels,
});

// Progressive viewport test: render only a viewport region using compositeDocumentRegion
// This returns only the viewport-sized buffer (true progressive rendering)
const viewportWidth = 1024;
const viewportHeight = 1024;
const viewportX = 1024;
const viewportY = 1024;

const denseProgressiveViewport = benchmark(() => {
  const output = compositeDocumentRegion(
    denseProgressiveDocument,
    { x: viewportX, y: viewportY, width: viewportWidth, height: viewportHeight },
    { tileCache: denseProgressiveCache },
  );

  if (output.length !== viewportWidth * viewportHeight * 4) {
    throw new Error(`Progressive viewport output size changed: expected ${viewportWidth * viewportHeight * 4}, got ${output.length}`);
  }
});

// Verify cache stats
const denseStats = denseProgressiveCache.stats;
console.log('Dense 4096×20 progressive cache stats:', {
  hits: denseStats.hits,
  misses: denseStats.misses,
  lastComposeFullyWarm: denseStats.lastComposeFullyWarm,
  allocatedBytes: denseStats.allocatedBytes,
  uniqueSpatialTileCount: denseStats.uniqueSpatialTileCount,
});

const denseBudget = baselines.scenarios['dense-4096-x20-progressive'];
if (denseBudget) {
  assertTiming('dense-4096-x20-progressive', denseProgressiveViewport, {
    maxMedianMs: denseBudget.maxMedianMs,
    maxP95Ms: denseBudget.maxP95Ms,
  });

  if (getAllocatedBytes(denseProgressiveCache) > denseBudget.maxAllocatedBytes) {
    throw new Error(
      `dense-4096-x20-progressive allocated ${getAllocatedBytes(denseProgressiveCache)} bytes (budget: ${denseBudget.maxAllocatedBytes})`,
    );
  }
}

// ============================================================================
// INCOMPLETE MILESTONE 3: 8192×8192 Sparse Document Progressive Composite
// ============================================================================

// Node benchmark for the largest sparse document: 8192² sparse progressive composite.
// Based on browser evidence: cold ~39ms, warm ~10ms, 36/16384 tiles.
// Uses mostly empty layers with sparse content patches.

// Create a sparse document with most layers being tiny patches
function sparseLayeredDocument(width: number, height: number, layerCount: number): ImageDocument {
  const layers: PixelLayer[] = [];

  // First layer: full coverage sparse background (mostly transparent)
  layers.push(createPixelLayer({
    id: 'background',
    name: 'Background',
    width,
    height,
    pixels: new Uint8ClampedArray(width * height * 4), // mostly transparent
    opacity: 1.0,
    blendMode: 'normal',
  }));

  // Add small sparse patches as "content" across layers
  const patchSize = 64;

  for (let i = 0; i < layerCount; i++) {
    const seed = i + 1;
    // Find a sparse non-overlapping patch location
    const x = ((seed * 73) % (width - patchSize));
    const y = ((seed * 137) % (height - patchSize));

    // Create layer with single small patch
    const pixels = new Uint8ClampedArray(width * height * 4);
    for (let py = 0; py < patchSize; py++) {
      for (let px = 0; px < patchSize; px++) {
        const offset = ((y + py) * width + (x + px)) * 4;
        pixels[offset] = (seed * 37) % 256;
        pixels[offset + 1] = (seed * 71) % 256;
        pixels[offset + 2] = (seed * 113) % 256;
        pixels[offset + 3] = 224;
      }
    }

    layers.push(createPixelLayer({
      id: `sparse-layer-${i}`,
      name: `Sparse Layer ${i}`,
      width,
      height,
      pixels,
      opacity: 0.8,
      blendMode: i % 3 === 0 ? 'multiply' : i % 3 === 1 ? 'screen' : 'normal',
    }));
  }

  return createDocument({
    id: `sparse-benchmark-${width}-${layerCount}`,
    name: 'Sparse Benchmark Document',
    width,
    height,
    layers,
  });
}

const sparseProgressiveDocument = sparseLayeredDocument(8192, 8192, 256);

// Tile cache for sparse large document
const sparseProgressiveCache = new CompositeTileCache({
  tileSize: 256,
  maxBytes: 64 * 1024 * 1024, // 64 MiB budget for sparse 8192²
});

// Cold reference for sparse
const sparseColdReference = (doc: ImageDocument) => compositeDocumentPixels(doc);

// First warm-up
sparseProgressiveCache.composite(sparseProgressiveDocument, {
  referenceComposite: sparseColdReference,
});

// Progressive viewport: small viewport over sparse content
const sparseViewportWidth = 512;
const sparseViewportHeight = 512;
const sparseViewportX = 2048;
const sparseViewportY = 2048;

const sparseProgressiveViewport = benchmark(() => {
  const output = compositeDocumentRegion(
    sparseProgressiveDocument,
    { x: sparseViewportX, y: sparseViewportY, width: sparseViewportWidth, height: sparseViewportHeight },
    { tileCache: sparseProgressiveCache },
  );

  if (output.length !== sparseViewportWidth * sparseViewportHeight * 4) {
    throw new Error('Sparse progressive viewport output size changed');
  }
});

const sparseStats = sparseProgressiveCache.stats;
console.log('Sparse 8192² progressive cache stats:', {
  hits: sparseStats.hits,
  misses: sparseStats.misses,
  lastComposeFullyWarm: sparseStats.lastComposeFullyWarm,
  allocatedBytes: sparseStats.allocatedBytes,
  uniqueSpatialTileCount: sparseStats.uniqueSpatialTileCount,
});

const sparseBudget = baselines.scenarios['sparse-8192-progressive'];
if (sparseBudget) {
  assertTiming('sparse-8192-progressive', sparseProgressiveViewport, {
    maxMedianMs: sparseBudget.maxMedianMs,
    maxP95Ms: sparseBudget.maxP95Ms,
  });

  if (getAllocatedBytes(sparseProgressiveCache) > sparseBudget.maxAllocatedBytes) {
    throw new Error(
      `sparse-8192-progressive allocated ${getAllocatedBytes(sparseProgressiveCache)} bytes (budget: ${sparseBudget.maxAllocatedBytes})`,
    );
  }
}

// ============================================================================
// INCOMPLETE MILESTONE 4: Sustained Progressive Pan Memory (Node)
// ============================================================================

// Node benchmark that validates sustained memory behavior under progressive pan
// operations with LRU eviction tracking.
// Based on browser evidence: peak 2.5 MiB, 1024 evictions, stayed within budget.

const memoryTestDocument = layeredDocument(1024, 1024, 6);

// Use a tight cache budget to force eviction behavior
const memoryTestCache = new CompositeTileCache({
  tileSize: 64,
  maxBytes: 2.5 * 1024 * 1024, // 2.5 MiB budget matching browser evidence
});

const memoryTestReference = (doc: ImageDocument) => compositeDocumentPixels(doc);
memoryTestCache.composite(memoryTestDocument, { referenceComposite: memoryTestReference });

// Simulate progressive panning: multiple viewport positions
const panPositions = [
  { x: 0, y: 0 },
  { x: 256, y: 0 },
  { x: 512, y: 0 },
  { x: 768, y: 0 },
  { x: 0, y: 256 },
  { x: 256, y: 256 },
  { x: 512, y: 256 },
  { x: 768, y: 256 },
  { x: 0, y: 512 },
  { x: 256, y: 512 },
  { x: 512, y: 512 },
  { x: 768, y: 512 },
  { x: 0, y: 768 },
  { x: 256, y: 768 },
  { x: 512, y: 768 },
  { x: 768, y: 768 },
];

const viewportBudget = 384;
const iterationCount = 48; // Match browser's 48 pan+edit iterations

let peakAllocatedBytes = 0;
const allocationHistory: number[] = [];

// Run sustained pan test using compositeDocumentRegion for true viewport rendering
for (let iteration = 0; iteration < iterationCount; iteration++) {
  // Cycle through pan positions
  const position = panPositions[iteration % panPositions.length];

  // Render viewport at this position (viewport-sized output)
  const output = compositeDocumentRegion(
    memoryTestDocument,
    { x: position.x, y: position.y, width: viewportBudget, height: viewportBudget },
    { tileCache: memoryTestCache },
  );

  if (output.length !== viewportBudget * viewportBudget * 4) {
    throw new Error('Sustained pan viewport output size changed');
  }

  // Track allocation metrics
  const currentAllocated = memoryTestCache.stats.allocatedBytes;
  peakAllocatedBytes = Math.max(peakAllocatedBytes, currentAllocated);
  allocationHistory.push(currentAllocated);

  if (iteration % 10 === 0) {
    console.log(`Sustained pan iteration ${iteration}: allocated=${currentAllocated}, peak=${peakAllocatedBytes}, evictions=${memoryTestCache.stats.evictions}`);
  }
}

const finalMemoryStats = memoryTestCache.stats;

console.log('Sustained pan memory test results:', {
  peakAllocatedBytes,
  finalAllocatedBytes: finalMemoryStats.allocatedBytes,
  totalEvictions: finalMemoryStats.evictions,
  uniqueSpatialTileCount: finalMemoryStats.uniqueSpatialTileCount,
  tileCount: finalMemoryStats.tileCount,
});

// Validate budget constraints
const memoryBudget = baselines.scenarios['sustained-pan-memory'];

if (peakAllocatedBytes > memoryBudget.maxCacheBytes) {
  throw new Error(
    `sustained-pan-memory exceeded cache budget: peak ${peakAllocatedBytes} bytes (budget: ${memoryBudget.maxCacheBytes})`,
  );
}

// Check bounded growth: second half should not exceed first half by more than factor
const halfPoint = Math.floor(allocationHistory.length / 2);
const firstHalfAvg = allocationHistory.slice(0, halfPoint).reduce((a, b) => a + b, 0) / halfPoint;
const secondHalfAvg = allocationHistory.slice(halfPoint).reduce((a, b) => a + b, 0) / (allocationHistory.length - halfPoint);

const growthFactor = secondHalfAvg / firstHalfAvg;
console.log('Sustained pan growth analysis:', {
  firstHalfAvg,
  secondHalfAvg,
  growthFactor,
});

if (growthFactor > memoryBudget.maxBoundedGrowthFactor) {
  throw new Error(
    `sustained-pan-memory unbounded growth: factor ${growthFactor.toFixed(2)} (budget: ${memoryBudget.maxBoundedGrowthFactor})`,
  );
}

// ============================================================================
// Run all existing benchmarks (unchanged)
// ============================================================================

const compositeDocument = layeredDocument(512, 512, 12);
const composite = benchmark(() => {
  const output = compositeDocumentPixels(compositeDocument);
  if (output.length !== 512 * 512 * 4) throw new Error('Composite output size changed');
});
assertTiming('composite-512-12', composite, baselines.scenarios['composite-512-12']);

// Dependency-keyed composite tile cache: warm re-composites must beat cold reference
// recomputes and remain fully warm (zero reference calls after the first populate).
const tileCacheDocument = layeredDocument(128, 128, 4);
const tileCache = new CompositeTileCache({ tileSize: 32, maxBytes: 16 * 1024 * 1024 });
const tileCacheReference = (document: ImageDocument) => compositeDocumentPixels(document);
tileCache.composite(tileCacheDocument, { referenceComposite: tileCacheReference });
const compositeWarm = benchmark(() => {
  const output = tileCache.composite(tileCacheDocument, {
    referenceComposite: tileCacheReference,
  });
  if (output.length !== 128 * 128 * 4) throw new Error('Warm composite tile cache size changed');
  if (!tileCache.stats.lastComposeFullyWarm) {
    throw new Error('Warm composite tile cache expected a fully warm compose');
  }
});
const compositeCold = benchmark(() => {
  const output = compositeDocumentPixels(tileCacheDocument);
  if (output.length !== 128 * 128 * 4) throw new Error('Cold composite size changed');
});
if (compositeWarm.medianMs >= compositeCold.medianMs) {
  throw new Error(
    `composite-tile-cache-warm-128-4 was not faster than cold reference: warm ${compositeWarm.medianMs.toFixed(2)} ms vs cold ${compositeCold.medianMs.toFixed(2)} ms`,
  );
}
const warmBudget = baselines.scenarios['composite-tile-cache-warm-128-4'];
if (warmBudget) assertTiming('composite-tile-cache-warm-128-4', compositeWarm, warmBudget);

// Larger warm-cache fixture representative of ordinary layered documents.
const largeCacheDocument = layeredDocument(512, 512, 8);
const largeCache = new CompositeTileCache({ tileSize: 64, maxBytes: 64 * 1024 * 1024 });
const largeReference = (document: ImageDocument) => compositeDocumentPixels(document);
largeCache.composite(largeCacheDocument, { referenceComposite: largeReference });
const compositeWarmLarge = benchmark(() => {
  const output = largeCache.composite(largeCacheDocument, {
    referenceComposite: largeReference,
  });
  if (output.length !== 512 * 512 * 4) throw new Error('Large warm composite size changed');
  if (!largeCache.stats.lastComposeFullyWarm) {
    throw new Error('Large warm composite expected fullyWarm');
  }
});
const compositeColdLarge = benchmark(() => {
  const output = compositeDocumentPixels(largeCacheDocument);
  if (output.length !== 512 * 512 * 4) throw new Error('Large cold composite size changed');
});
if (compositeWarmLarge.medianMs >= compositeColdLarge.medianMs) {
  throw new Error(
    `composite-tile-cache-warm-512-8 was not faster than cold: warm ${compositeWarmLarge.medianMs.toFixed(2)} ms vs cold ${compositeColdLarge.medianMs.toFixed(2)} ms`,
  );
}
const largeWarmBudget = baselines.scenarios['composite-tile-cache-warm-512-8'];
if (largeWarmBudget) {
  assertTiming('composite-tile-cache-warm-512-8', compositeWarmLarge, largeWarmBudget);
}

const brushLayer = solidLayer('brush', 2048, 2048, 5);
const brush = benchmark(() => {
  const patch = paintStroke(
    brushLayer,
    [
      { x: 128, y: 128, pressure: 0.5 },
      { x: 1920, y: 1920, pressure: 1 },
    ],
    { mode: 'source-over', size: 48, hardness: 0.8, opacity: 0.75, color: [20, 180, 120, 255] },
  );
  if (patch.width === 0 || patch.height === 0) throw new Error('Brush benchmark produced no patch');
});
assertTiming('brush-2048-diagonal', brush, baselines.scenarios['brush-2048-diagonal']);

const sparseStore = TiledPixelStore.empty(32_768, 32_768);
const sparsePatch = {
  x: 16_000,
  y: 16_000,
  width: 64,
  height: 64,
  pixels: new Uint8ClampedArray(64 * 64 * 4).fill(180),
};
let sparseAllocatedBytes = 0;
const tiled = benchmark(() => {
  const result = sparseStore.write(sparsePatch);
  sparseAllocatedBytes = result.store.allocatedByteLength;
  if (result.changedTileKeys.length !== 1)
    throw new Error('Sparse patch crossed an unexpected tile');
});
const tiledBudget = baselines.scenarios['tiled-sparse-32768-patch'];
assertTiming('tiled-sparse-32768-patch', tiled, tiledBudget);
if (sparseAllocatedBytes > tiledBudget.maxAllocatedBytes) {
  throw new Error(`tiled-sparse-32768-patch allocated ${String(sparseAllocatedBytes)} bytes`);
}

const sparseCoverageStore = TiledCoverageStore.empty(32_768, 32_768);
const sparseCoveragePatch = {
  x: 16_000,
  y: 16_000,
  width: 64,
  height: 64,
  coverage: new Uint8ClampedArray(64 * 64).fill(180),
};
let sparseCoverageAllocatedBytes = 0;
const tiledCoverage = benchmark(() => {
  const result = sparseCoverageStore.write(sparseCoveragePatch);
  sparseCoverageAllocatedBytes = result.store.allocatedByteLength;
  if (result.changedTileKeys.length !== 1) {
    throw new Error('Sparse coverage patch crossed an unexpected tile');
