import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import {
  createDocument,
  createPixelLayer,
  type ImageDocument,
  type PixelLayer,
} from '@freetoshop/core-document';
import { paintStroke } from '@freetoshop/raster-engine';
import {
  CompositeTileCache,
  compositeDocumentPixels,
  compositeDocumentRegion,
} from '@freetoshop/renderer';
import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

interface TimingBudget {
  readonly maxMedianMs: number;
  readonly maxP95Ms: number;
}

interface Baselines {
  readonly schemaVersion: 1;
  readonly profile: string;
  readonly scenarios: {
    readonly 'composite-512-12': TimingBudget;
    readonly 'brush-2048-diagonal': TimingBudget;
    readonly 'tiled-sparse-32768-patch': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'coverage-sparse-32768-patch': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'document-1024-8-memory': { readonly maxArrayBufferAmplification: number };
    readonly 'composite-tile-cache-warm-128-4'?: TimingBudget;
    readonly 'composite-tile-cache-warm-512-8'?: TimingBudget;
    readonly 'dense-4096-x20-progressive': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'sparse-8192-progressive': TimingBudget & { readonly maxAllocatedBytes: number };
    readonly 'sustained-pan-memory': { readonly maxCacheBytes: number; readonly maxBoundedGrowthFactor: number };
  };
}

interface TimingResult {
  readonly medianMs: number;
  readonly p95Ms: number;
  readonly samplesMs: readonly number[];
}

const baselinePath = fileURLToPath(new URL('../baselines.json', import.meta.url));
const baselines = JSON.parse(await readFile(baselinePath, 'utf8')) as Baselines;

function solidLayer(id: string, width: number, height: number, seed: number): PixelLayer {
  const pixels = new Uint8ClampedArray(width * height * 4);
  for (let offset = 0; offset < pixels.length; offset += 4) {
    pixels[offset] = (seed * 37 + offset / 4) % 256;
    pixels[offset + 1] = (seed * 71 + offset / 16) % 256;
    pixels[offset + 2] = (seed * 113 + offset / 64) % 256;
    pixels[offset + 3] = 224;
  }
  return createPixelLayer({
    id,
    name: id,
    width,
    height,
    pixels,
    opacity: 0.8,
    blendMode: seed % 3 === 0 ? 'multiply' : seed % 3 === 1 ? 'screen' : 'normal',
  });
}

function layeredDocument(width: number, height: number, layerCount: number): ImageDocument {
  return createDocument({
    id: `benchmark-${String(width)}-${String(layerCount)}`,
    name: 'Benchmark document',
    width,
    height,
    layers: Array.from({ length: layerCount }, (_, index) =>
      solidLayer(`layer-${String(index)}`, width, height, index + 1),
    ),
  });
}

function percentile(sorted: readonly number[], fraction: number): number {
  const index = Math.min(sorted.length - 1, Math.ceil(sorted.length * fraction) - 1);
  return sorted[index] ?? 0;
}

function benchmark(operation: () => void, warmups = 1, samples = 5): TimingResult {
  for (let index = 0; index < warmups; index += 1) operation();
  const durations: number[] = [];
  for (let index = 0; index < samples; index += 1) {
    const started = performance.now();
    operation();
    durations.push(performance.now() - started);
  }
  durations.sort((left, right) => left - right);
  return {
    medianMs: percentile(durations, 0.5),
    p95Ms: percentile(durations, 0.95),
    samplesMs: durations,
  };
}

function assertTiming(name: string, result: TimingResult, budget: TimingBudget): void {
  if (result.medianMs > budget.maxMedianMs || result.p95Ms > budget.maxP95Ms) {
    throw new Error(
      `${name} exceeded its baseline: median ${result.medianMs.toFixed(1)} ms, p95 ${result.p95Ms.toFixed(1)} ms`,
    );
  }
}

function getAllocatedBytes(cache: CompositeTileCache): number {
  return cache.stats.allocatedBytes;
}

function getTotalEvictions(cache: CompositeTileCache): number {
  return cache.stats.evictions;
}

async function settleMemoryAccounting(): Promise<void> {
  globalThis.gc?.();
  await new Promise<void>((resolve) => setImmediate(resolve));
  globalThis.gc?.();
  await new Promise<void>((resolve) => setImmediate(resolve));
  globalThis.gc?.();
}

// ============================================================================
// INCOMPLETE MILESTONE 2: Dense 4096×4096 × 20 Layers Progressive Composite
// ============================================================================

// Node benchmark for the largest dense fixture: 4096² × 20 layer progressive composite.
// Based on browser evidence: cold ~232ms, warm ~45ms.
// Uses compositeDocumentRegion for true viewport-only rendering (returns only viewport pixels)

const denseProgressiveDocument = layeredDocument(4096, 4096, 20);

// Cache for warm re-composites
const denseProgressiveCache = new CompositeTileCache({
  tileSize: 256,
  maxBytes: 256 * 1024 * 1024, // 256 MiB budget for this large fixture
});

// First warm-up: populate the cache with full composite
denseProgressiveCache.composite(denseProgressiveDocument, {
  referenceComposite: compositeDocumentPixels,
});

// Progressive viewport test: render only a viewport region using compositeDocumentRegion
// This returns only the viewport-sized buffer (true progressive rendering)
const viewportWidth = 1024;
const viewportHeight = 1024;
const viewportX = 1024;
const viewportY = 1024;

const denseProgressiveViewport = benchmark(() => {
  const output = compositeDocumentRegion(
    denseProgressiveDocument,
    { x: viewportX, y: viewportY, width: viewportWidth, height: viewportHeight },
    { tileCache: denseProgressiveCache },
  );

  if (output.length !== viewportWidth * viewportHeight * 4) {
    throw new Error(`Progressive viewport output size changed: expected ${viewportWidth * viewportHeight * 4}, got ${output.length}`);
  }
});

// Verify cache stats
const denseStats = denseProgressiveCache.stats;
console.log('Dense 4096×20 progressive cache stats:', {
  hits: denseStats.hits,
  misses: denseStats.misses,
  lastComposeFullyWarm: denseStats.lastComposeFullyWarm,
  allocatedBytes: denseStats.allocatedBytes,
  uniqueSpatialTileCount: denseStats.uniqueSpatialTileCount,
});

const denseBudget = baselines.scenarios['dense-4096-x20-progressive'];
if (denseBudget) {
  assertTiming('dense-4096-x20-progressive', denseProgressiveViewport, {
    maxMedianMs: denseBudget.maxMedianMs,
    maxP95Ms: denseBudget.maxP95Ms,
  });

  if (getAllocatedBytes(denseProgressiveCache) > denseBudget.maxAllocatedBytes) {
    throw new Error(
      `dense-4096-x20-progressive allocated ${getAllocatedBytes(denseProgressiveCache)} bytes (budget: ${denseBudget.maxAllocatedBytes})`,
    );
  }
}

// ============================================================================
// INCOMPLETE MILESTONE 3: 8192×8192 Sparse Document Progressive Composite
// ============================================================================

// Node benchmark for the largest sparse document: 8192² sparse progressive composite.
// Based on browser evidence: cold ~39ms, warm ~10ms, 36/16384 tiles.
// Uses mostly empty layers with sparse content patches.

// Create a sparse document with most layers being tiny patches
function sparseLayeredDocument(width: number, height: number, layerCount: number): ImageDocument {
  const layers: PixelLayer[] = [];

  // First layer: full coverage sparse background (mostly transparent)
  layers.push(createPixelLayer({
    id: 'background',
    name: 'Background',
    width,
    height,
    pixels: new Uint8ClampedArray(width * height * 4), // mostly transparent
    opacity: 1.0,
    blendMode: 'normal',
  }));

  // Add small sparse patches as "content" across layers
  const patchSize = 64;

  for (let i = 0; i < layerCount; i++) {
    const seed = i + 1;
    // Find a sparse non-overlapping patch location
    const x = ((seed * 73) % (width - patchSize));
    const y = ((seed * 137) % (height - patchSize));

    // Create layer with single small patch
    const pixels = new Uint8ClampedArray(width * height * 4);
    for (let py = 0; py < patchSize; py++) {
      for (let px = 0; px < patchSize; px++) {
        const offset = ((y + py) * width + (x + px)) * 4;
        pixels[offset] = (seed * 37) % 256;
        pixels[offset + 1] = (seed * 71) % 256;
        pixels[offset + 2] = (seed * 113) % 256;
        pixels[offset + 3] = 224;
      }
    }

    layers.push(createPixelLayer({
      id: `sparse-layer-${i}`,
      name: `Sparse Layer ${i}`,
      width,
      height,
      pixels,
      opacity: 0.8,
      blendMode: i % 3 === 0 ? 'multiply' : i % 3 === 1 ? 'screen' : 'normal',
    }));
  }

  return createDocument({
    id: `sparse-benchmark-${width}-${layerCount}`,
    name: 'Sparse Benchmark Document',
    width,
    height,
    layers,
  });
}

const sparseProgressiveDocument = sparseLayeredDocument(8192, 8192, 256);

// Tile cache for sparse large document
const sparseProgressiveCache = new CompositeTileCache({
  tileSize: 256,
  maxBytes: 64 * 1024 * 1024, // 64 MiB budget for sparse 8192²
});

// Cold reference for sparse
const sparseColdReference = (doc: ImageDocument) => compositeDocumentPixels(doc);

// First warm-up
sparseProgressiveCache.composite(sparseProgressiveDocument, {
  referenceComposite: sparseColdReference,
});

// Progressive viewport: small viewport over sparse content
const sparseViewportWidth = 512;
const sparseViewportHeight = 512;
const sparseViewportX = 2048;
