const sparseStore = TiledPixelStore.empty(32_768, 32_768);
const sparsePatch = {
  x: 16_000,
  y: 16_000,
  width: 64,
  height: 64,
  pixels: new Uint8ClampedArray(64 * 64 * 4).fill(180),
};
let sparseAllocatedBytes = 0;
const tiled = benchmark(() => {
